import{_ as t,o as a,c as o,a2 as r}from"./chunks/framework.BXzK3EA4.js";const n="/assets/nubra_new1.CxsRF-4C.PNG",i="/assets/nubra_new2.pLHHubX-.PNG",s="/assets/nubra_new3.D4MCYjSN.PNG",c="/assets/nubra_new5.BJ3iuGzN.PNG",d="/assets/nubra_new4.5YgCKkhh.PNG",_=JSON.parse('{"title":"Nubra","description":"","frontmatter":{},"headers":[],"relativePath":"connect-brokers/brokers/nubra.md","filePath":"connect-brokers/brokers/nubra.md"}'),l={name:"connect-brokers/brokers/nubra.md"};function u(h,e,g,p,b,f){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="nubra" tabindex="-1">Nubra <a class="header-anchor" href="#nubra" aria-label="Permalink to &quot;Nubra&quot;">​</a></h1><p>Nubra, by Zanskar Securities Private Limited, is a modern trading platform built for algorithmic and institutional traders. It provides REST-like resource-based endpoints with low-latency order execution, comprehensive market data access including quotes, Greeks, and historical candles, and a phone OTP plus MPIN login, making it an excellent choice for automated trading with Tradeboard.</p><ol><li><strong>Navigate</strong> to the Nubra&#39;s Dashboard Login <a href="https://nubra.io/" target="_blank" rel="noreferrer">https://nubra.io/</a> Open Demat</li></ol><figure><img src="'+n+'" alt=""><figcaption></figcaption></figure><ol start="2"><li>Tradeboard logs in to Nubra with two things you already have, so there is no API key to generate: <ol><li>Your <strong>registered mobile number</strong>, which receives the login OTP</li><li>Your <strong>6-digit MPIN</strong>, which is exchanged for the session token</li></ol></li></ol><figure><img src="'+i+'" alt=""><figcaption></figcaption></figure><ol start="3"><li>Click on the <strong>Profile</strong> icon located at the top-right corner of the page</li></ol><figure><img src="'+s+'" alt=""><figcaption></figcaption></figure><figure><img src="'+c+'" alt=""><figcaption></figcaption></figure><ol start="3"><li>To Register the static IP ,scroll down the left panel. Select <strong>Resources-Update Static IP- Update - Validate</strong>.</li></ol><figure><img src="'+d+`" alt=""><figcaption></figcaption></figure><h3 id="environment-configuration" tabindex="-1"><strong>Environment Configuration</strong> <a class="header-anchor" href="#environment-configuration" aria-label="Permalink to &quot;**Environment Configuration**&quot;">​</a></h3><p>Nubra does not issue an API key and secret pair. Tradeboard reuses the two <code>BROKER_API_*</code> variables to carry your login details instead:</p><ul><li><code>BROKER_API_KEY</code> holds your <strong>registered mobile number</strong>, the one Nubra sends the login OTP to</li><li><code>BROKER_API_SECRET</code> holds your <strong>6-digit MPIN</strong></li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>BROKER_API_KEY = &#39;your_nubra_registered_mobile_number&#39;</span></span>
<span class="line"><span>BROKER_API_SECRET = &#39;your_nubra_mpin&#39;</span></span>
<span class="line"><span>REDIRECT_URL = &#39;http://127.0.0.1:5000/nubra/callback&#39;</span></span></code></pre></div><h3 id="connecting-from-tradeboard" tabindex="-1">Connecting from Tradeboard <a class="header-anchor" href="#connecting-from-tradeboard" aria-label="Permalink to &quot;Connecting from Tradeboard&quot;">​</a></h3><p>When you click Connect on the Nubra broker page, Tradeboard sends an OTP to the registered mobile number and opens the OTP entry screen. Enter the code you received to finish the login. Reloading that screen does not resend the code: only a fresh Connect from the broker page dispatches a new OTP, and each code can be used once.</p><p>If your account has TOTP enrolled, Tradeboard still forces the SMS path, so an authenticator app is not required.</p><h3 id="static-ip" tabindex="-1">Static IP <a class="header-anchor" href="#static-ip" aria-label="Permalink to &quot;Static IP&quot;">​</a></h3><p>Nubra exposes a read-only static IP check. Tradeboard surfaces it, but there is no API to register or change the IPs: that is done through Nubra using the <strong>Resources - Update Static IP</strong> screen shown above. An account with no registered IPs reports that state rather than failing.</p><p>Integrating with <strong>Nubra APIs</strong> unlocks the ability to automate strategies, execute trades, and analyze data directly within your own infrastructure. When used with <strong>Tradeboard</strong>, you can self-host and run your entire algo trading stack, with full control and zero vendor lock-in.</p><h3 id="supported-exchanges" tabindex="-1">Supported Exchanges <a class="header-anchor" href="#supported-exchanges" aria-label="Permalink to &quot;Supported Exchanges&quot;">​</a></h3><p>Tradeboard reads this plugin&#39;s exchange list from <code>broker/nubra/plugin.json</code> and serves it to the app, so symbol search, the Strategy Builder and the tools pages only offer what the plugin actually handles.</p><ul><li><strong>Tradable:</strong> <code>NSE</code>, <code>BSE</code>, <code>NFO</code>, <code>BFO</code>, <code>MCX</code></li><li><strong>Index feeds:</strong> <code>NSE_INDEX</code>, <code>BSE_INDEX</code></li></ul>`,24)])])}const P=t(l,[["render",u]]);export{_ as __pageData,P as default};
